 function groupAt(p){const seen=new Set([p]),todo=[p],stones=[],libs=new Set(),c=b[p];while(todo.length){const q=todo.pop();stones.push(q);for(const n of neighbors(q)){if(b[n]===".")libs.add(n);else if(b[n]===c&&!seen.has(n)){seen.add(n);todo.push(n);}}}return {stones,libs};}
 function actualMove(color,p){moves.push({number:moves.length+1,color,move:p});if(p==="pass")return;if(b[p]!==".")throw Error("occupied "+p);b[p]=color;const removed=[],checked=new Set();for(const n of neighbors(p)){if(b[n]!=="."&&b[n]!==color&&!checked.has(n)){const g=groupAt(n);g.stones.forEach(s=>checked.add(s));if(g.libs.size===0){g.stones.forEach(s=>{removed.push(s);b[s]=".";});}}}captured[color]+=removed.length;if(groupAt(p).libs.size===0)throw Error("suicide actual "+p);if(removed.length)events.push({number:moves.length,color,move:p,captured:removed.sort()});}
